 private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String value){if(root==null)return null;CharSequence text=root.getText(),description=root.getContentDescription();if((text!=null&&text.toString().toLowerCase(Locale.ROOT).contains(value.toLowerCase(Locale.ROOT)))||(description!=null&&description.toString().equalsIgnoreCase(value)))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=node(root.getChild(i),value);if(n!=null)return n;}return null;}
 private boolean exists(String value){return node(getUiAutomation().getRootInActiveWindow(),value)!=null;}
 private void click(String value)throws Exception{AccessibilityNodeInfo n=node(getUiAutomation().getRootInActiveWindow(),value);if(n==null)throw new AssertionError("UI missing: "+value);while(n!=null&&!n.isClickable())n=n.getParent();if(n==null||!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Click failed: "+value);sleep(350);}
 private AccessibilityNodeInfo scrollable(AccessibilityNodeInfo root){if(root==null)return null;if(root.isScrollable())return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=scrollable(root.getChild(i));if(n!=null)return n;}return null;}
 private void reveal(String value)throws Exception{sleep(400);for(int i=0;i<8&&!exists(value);i++){AccessibilityNodeInfo list=scrollable(getUiAutomation().getRootInActiveWindow());if(list==null)break;list.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);sleep(400);}await(value,3);}
 private void await(String value,int seconds)throws Exception{for(int i=0;i<seconds*2&&!exists(value);i++)sleep(500);check(exists(value),"UI: "+value);}
